10	    {
11	      packages.entire =
12	        let
13	          version = "0.10.2";
14	          sources = {
15	            "aarch64-darwin" = {
16	              target = "darwin_arm64";
17	              hash = "REDACTED";
18	            };
19	            "x86_64-darwin" = {
20	              target = "darwin_amd64";
21	              hash = "REDACTED";
22	            };
23	            "aarch64-linux" = {
