//! The core domain's pure laws over arbitrary inputs
//! (docs/testing/property.md). Email canonicalization is total and
//! idempotent, the UUIDv7 layout orders by its millisecond prefix, and the
//! id format round-trips through its parser, each over a swept space rather
//! than one fixed example.

use core::str::FromStr;

use hegel::TestCase;
use hegel::generators as gs;

use sesame_core::ids::UserId;
use sesame_core::model::{EMAIL_MAX_LEN, EmailAddress, TimestampMillis};
use sesame_core::seams::rng::layout;

const LOCAL_ALPHABET: &[u8] =
    b"REDACTED._%+-";
const DOMAIN_ALPHABET: &[u8] = b"REDACTED.-";

fn draw_with_alphabet(tc: &TestCase, alphabet: &[u8]) -> String {
    let bytes = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(60));
    let mut out = String::from('a');
    out.extend(
        bytes
            .iter()
            .map(|b| alphabet[usize::from(*b) % alphabet.len()] as char),
    );
    out
}

#[hegel::test(test_cases = 256)]
fn email_construction_is_total(tc: TestCase) {
    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(300));
    let raw = String::from_utf8_lossy(&bytes);
    // Construction answers Ok or a typed rejection, never a panic, for any
    // byte string at all.
    if let Ok(email) = EmailAddress::new(&raw) {
        assert!(email.as_str().len() <= EMAIL_MAX_LEN);
        assert_eq!(email.as_str(), email.as_str().to_lowercase());
        let again = EmailAddress::new(email.as_str()).expect("the canonical form parses");
        assert_eq!(email, again, "canonicalization is idempotent");
    }
}

#[hegel::test(test_cases = 256)]
fn canonicalization_is_fold_equivalent(tc: TestCase) {
    let local = draw_with_alphabet(&tc, LOCAL_ALPHABET);
    let domain = draw_with_alphabet(&tc, DOMAIN_ALPHABET);
    let raw = format!("{local}@{domain}");
    let folded: String = raw
        .chars()
        .map(|c| {
            if tc.draw(gs::booleans()) {
                c.to_ascii_uppercase()
            } else {
                c
            }
        })
        .collect();
    let original = EmailAddress::new(&raw).expect("the constrained alphabet is valid");
    let variant = EmailAddress::new(&folded).expect("case folding keeps the input valid");
    assert_eq!(original, variant, "case never changes the canonical form");
    let twice = EmailAddress::new(original.as_str()).expect("the canonical form parses");
    assert_eq!(original, twice);
}

#[hegel::test(test_cases = 256)]
fn v7_orders_strictly_by_millisecond(tc: TestCase) {
    // Bounded so the draw never crosses the layout's 48-bit timestamp
    // window; the ordering law lives inside it.
    let ms = tc.draw(gs::integers::<u64>().max_value(1u64 << 40));
    let delta = tc.draw(gs::integers::<u64>().min_value(1).max_value(1_000_000));
    let earlier = layout::v7(
        TimestampMillis::new(ms),
        tc.draw(gs::integers::<u16>()),
        tc.draw(gs::integers::<u64>()),
    );
    let later = layout::v7(
        TimestampMillis::new(ms + delta),
        tc.draw(gs::integers::<u16>()),
        tc.draw(gs::integers::<u64>()),
    );
    assert!(earlier < later, "v7 ids order by their millisecond prefix");
    for id in [earlier, later] {
        assert_eq!(id.get_version_num(), 7);
        assert_eq!(id.get_variant(), uuid::Variant::RFC4122);
    }
}

#[hegel::test(test_cases = 128)]
fn id_format_parse_round_trips(tc: TestCase) {
    let id = UserId::from(layout::v7(
        TimestampMillis::new(tc.draw(gs::integers::<u64>())),
        tc.draw(gs::integers::<u16>()),
        tc.draw(gs::integers::<u64>()),
    ));
    let parsed = UserId::from_str(&id.to_string()).expect("the own format parses");
    assert_eq!(id, parsed);
}

