/**
 * The narinfo document: parsing, serialising, and the reference graph.
 *
 * A narinfo is a flat list of `Key: value` lines describing one store path
 * (`docs/contracts.md` §The narinfo format). cachet cares about it for two reasons: the `URL`
 * field names the NAR that must already exist before the narinfo may be stored
 * (Invariant NEVER-DANGLE), and the `References` field is the graph the collector walks
 * (ADR 0001) — there is no other copy of it anywhere.
 *
 * Unknown fields are preserved verbatim. We are a cache, not an authority on the format. A
 * field we do not understand must survive a store-and-serve cycle untouched, or we corrupt
 * artifacts for a client that does understand it — and clients verify signatures over content we
 * would have altered.
 *
 * The parser is total: arbitrary bytes yield a typed failure, never a throw
 * (Invariant CLIENT-CANNOT-CRASH).
 *
 * @module
 */

import { NARINFO_BYTES_MAX, NARINFO_LINES_MAX, NARINFO_REFERENCES_MAX } from '../constants.js';
import { fail, ok, type Result } from '../result.js';
import type { NarKey, StorePathHash } from '../types.js';
import { parseNarKey, parseStorePath, parseStorePathBasename } from './keys.js';

/** The fields cachet reads, plus everything it does not. */
export interface Narinfo {
    /** The full `/nix/store/<hash>-<name>` path this document describes. */
    readonly storePath: string;
    /** The NAR's bucket key. The object the write path checks for. */
    readonly url: NarKey;
    /** How the NAR is compressed. Defaults to `bzip2` when absent, as Nix does. */
    readonly compression: string;
    /** Hash of the compressed NAR. Absent for some uncompressed layouts. */
    readonly fileHash: string | undefined;
    readonly fileSizeBytes: number | undefined;
    /** Hash of the uncompressed NAR — what `nix store verify` checks. */
    readonly narHash: string;
    readonly narSizeBytes: number;
    /** `<hash>-<name>` basenames. The collector's edge list. */
    readonly references: readonly string[];
    /** May appear more than once; clients verify these against their trusted keys. */
    readonly signatures: readonly string[];
    /** Every line whose key we do not recognise, verbatim and in order. */
    readonly extraLines: readonly string[];
}

/** why: Nix's own default when the field is absent (`docs/contracts.md`). */
const DEFAULT_COMPRESSION = 'bzip2';

const SINGLE_VALUE_FIELDS = [
    'StorePath',
    'URL',
    'Compression',
    'FileHash',
    'FileSize',
    'NarHash',
    'NarSize',
    'References',
] as const;

/** Fields collected during a parse, before validation. */
interface FieldBag {
    readonly single: Map<string, string>;
    readonly signatures: string[];
    readonly extraLines: string[];
}

/** A non-negative integer, strictly — no signs, no whitespace, no exponents. */
function parseByteCount(text: string, field: string): Result<number> {
    if (!/^\d+$/.test(text)) {
        return fail('malformed_narinfo', `${field} is a non-negative integer`);
    }
    const value = Number(text);
    if (!Number.isSafeInteger(value)) {
        return fail('malformed_narinfo', `${field} is too large to represent exactly`);
    }
    return ok(value);
}

/** A hash field: opaque to us, but it must at least be one non-empty token. */
function checkHash(text: string, field: string): Result<string> {
    if (text.length === 0 || /\s/.test(text)) {
        return fail('malformed_narinfo', `${field} is a single non-empty token`);
    }
    return ok(text);
}

/** Split the document into fields, keeping unknown lines aside. */
function collectFields(text: string): Result<FieldBag> {
    const lines = text.split('\n');
    if (lines.length > NARINFO_LINES_MAX) {
        return fail(
            'malformed_narinfo',
            `a narinfo has at most ${String(NARINFO_LINES_MAX)} lines`,
        );
    }

    const single = new Map<string, string>();
    const signatures: string[] = [];
    const extraLines: string[] = [];

    for (const line of lines) {
        // A trailing newline yields one empty final element; blank lines are otherwise not
        // meaningful in this format, so they are dropped rather than preserved.
        if (line.length === 0) {
            continue;
        }
        const separator = line.indexOf(': ');
        if (separator <= 0) {
            return fail('malformed_narinfo', 'every narinfo line is "Key: value"');
        }
        const key = line.slice(0, separator);
        const value = line.slice(separator + 2);

        if (key === 'Sig') {
            signatures.push(value);
            continue;
        }
        if (!(SINGLE_VALUE_FIELDS as readonly string[]).includes(key)) {
            extraLines.push(line);
            continue;
        }
        // why: a duplicated single-valued field is a document we cannot interpret without
        // guessing which one is authoritative, so it is refused rather than resolved.
        if (single.has(key)) {
            return fail('malformed_narinfo', `${key} appears more than once`);
        }
        single.set(key, value);
    }

    return ok({ single, signatures, extraLines });
}

/** Validate the `References` field into checked basenames. */
function parseReferences(raw: string | undefined): Result<readonly string[]> {
    if (raw === undefined || raw.length === 0) {
        return ok([]);
    }
    const entries = raw.split(' ').filter((entry) => entry.length > 0);
    if (entries.length > NARINFO_REFERENCES_MAX) {
        // Invariant BOUNDED-WORK: this also caps the closure walk's fan-out from one node.
        return fail(
            'malformed_narinfo',
            `References exceeds ${String(NARINFO_REFERENCES_MAX)} entries`,
        );
    }
    for (const entry of entries) {
        const parsed = parseStorePathBasename(entry);
        if (!parsed.ok) {
            return fail('malformed_narinfo', `References contains an invalid store path basename`);
        }
    }
    return ok(entries);
}

/**
 * Parse a narinfo document.
 *
 * @example
 * ```ts
 * const parsed = parseNarinfo(await request.text());
 * if (!parsed.ok) return parsed;
 * const narKey = parsed.value.url;   // the object NEVER-DANGLE requires to exist
 * ```
 */
export function parseNarinfo(text: string): Result<Narinfo> {
    // Bound before splitting, so a huge document costs a length comparison.
    if (text.length > NARINFO_BYTES_MAX) {
        return fail('body_too_large', `a narinfo exceeds ${String(NARINFO_BYTES_MAX)} bytes`);
    }

    const collected = collectFields(text);
    if (!collected.ok) {
        return collected;
    }
    const { single, signatures, extraLines } = collected.value;

    const storePathText = single.get('StorePath');
    const urlText = single.get('URL');
    const narHashText = single.get('NarHash');
    const narSizeText = single.get('NarSize');
    if (
        storePathText === undefined ||
        urlText === undefined ||
        narHashText === undefined ||
        narSizeText === undefined
    ) {
        return fail('malformed_narinfo', 'a narinfo requires StorePath, URL, NarHash, and NarSize');
    }

    const storePath = parseStorePath(storePathText);
    if (!storePath.ok) {
        return fail('malformed_narinfo', 'StorePath is not a valid store path');
    }
    const url = parseNarKey(urlText);
    if (!url.ok) {
        return fail('malformed_narinfo', 'URL is not a valid NAR key');
    }
    const narHash = checkHash(narHashText, 'NarHash');
    if (!narHash.ok) {
        return narHash;
    }
    const narSizeBytes = parseByteCount(narSizeText, 'NarSize');
    if (!narSizeBytes.ok) {
        return narSizeBytes;
    }
    const references = parseReferences(single.get('References'));
    if (!references.ok) {
        return references;
    }

    const optional = parseOptionalFileFields(single);
    if (!optional.ok) {
        return optional;
    }

    return ok({
        storePath: storePathText,
        url: url.value,
        compression: single.get('Compression') ?? DEFAULT_COMPRESSION,
        fileHash: optional.value.fileHash,
        fileSizeBytes: optional.value.fileSizeBytes,
        narHash: narHash.value,
        narSizeBytes: narSizeBytes.value,
        references: references.value,
        signatures,
        extraLines,
    });
}

/** `FileHash` and `FileSize` are optional, but must be well-formed when present. */
function parseOptionalFileFields(
    single: Map<string, string>,
): Result<{ fileHash: string | undefined; fileSizeBytes: number | undefined }> {
    const fileHashText = single.get('FileHash');
    const fileSizeText = single.get('FileSize');

    let fileHash: string | undefined;
    if (fileHashText !== undefined) {
        const checked = checkHash(fileHashText, 'FileHash');
        if (!checked.ok) {
            return checked;
        }
        fileHash = checked.value;
    }

    let fileSizeBytes: number | undefined;
    if (fileSizeText !== undefined) {
        const parsed = parseByteCount(fileSizeText, 'FileSize');
        if (!parsed.ok) {
            return parsed;
        }
        fileSizeBytes = parsed.value;
    }

    return ok({ fileHash, fileSizeBytes });
}

/**
 * Serialise a narinfo back to its wire form.
 *
 * Fields are emitted in a canonical order and unknown lines follow verbatim, so
 * `parseNarinfo(serializeNarinfo(x))` reproduces `x`. Serialising does not reproduce the original
 * document byte for byte, because field order in the input is not meaningful and is not preserved.
 * No information is lost, so a client's signature over the content stays valid.
 */
export function serializeNarinfo(narinfo: Narinfo): string {
    const lines = [
        `StorePath: ${narinfo.storePath}`,
        `URL: ${narinfo.url}`,
        `Compression: ${narinfo.compression}`,
    ];

    if (narinfo.fileHash !== undefined) {
        lines.push(`FileHash: ${narinfo.fileHash}`);
    }
    if (narinfo.fileSizeBytes !== undefined) {
        lines.push(`FileSize: ${String(narinfo.fileSizeBytes)}`);
    }

    lines.push(`NarHash: ${narinfo.narHash}`, `NarSize: ${String(narinfo.narSizeBytes)}`);
    lines.push(`References: ${narinfo.references.join(' ')}`);

    for (const signature of narinfo.signatures) {
        lines.push(`Sig: ${signature}`);
    }
    lines.push(...narinfo.extraLines);

    return `${lines.join('\n')}\n`;
}

/**
 * The store-path hashes this narinfo depends on.
 *
 * This is the collector's edge list. Total by construction: `parseNarinfo` already validated
 * every reference, so the hashes are recoverable without re-validating.
 */
export function referenceHashes(narinfo: Narinfo): readonly StorePathHash[] {
    const hashes: StorePathHash[] = [];
    for (const reference of narinfo.references) {
        const parsed = parseStorePathBasename(reference);
        // A parsed narinfo cannot hold an invalid reference; skipping rather than asserting keeps
        // the collector's walk resilient to an object written before a validation change.
        if (parsed.ok) {
            hashes.push(parsed.value.hash);
        }
    }
    return hashes;
}

