1	/**
2	 * The lease document — one per project, under `roots/{project}`.
3	 *
4	 * A lease is cachet's only garbage-collection state. There is no database: the collector
5	 * reads these documents, walks the closures of the paths they name, and treats everything unmarked
6	 * and older than the grace window as collectable (ADR 0001).
7	 *
8	 * Two consequences follow:
9	 *
10	 * - Last write wins. A lease asserts what a project needs now rather than a history of what it once
11	 *   needed. A renewal replaces the previous document wholesale, so a path that drops out of the
12	 *   closure stops being protected — which is the only reason the cache does not grow forever.
13	 * - Provenance comes from the verified token, never from the request body. The verifier rebuilds
14	 *   from what a lease records, so a commit SHA a client could choose for itself would be worthless.
15	 *
16	 * @module
17	 */
18	
19	import { UNKNOWN_CLAIM } from '../constants.js';
20	import { fail, ok, type Result } from '../result.js';
21	import { parseProjectName, type ProjectName, type UnixMillis } from '../types.js';
22	
23	/** What `roots/{project}` holds. */
24	export interface LeaseDocument {
25	    readonly project: ProjectName;
26	    /** When this lease was last renewed. The collector compares it against lease retention. */
27	    readonly renewedAtMs: UnixMillis;
28	    /** `owner/repo`, from the verified token. */
29	    readonly repository: string;
30	    /** The ref that renewed it — always the configured default branch, by the time it is written. */
31	    readonly ref: string;
32	    /** The workflow run, from the verified token. */
33	    readonly runId: string;
34	    /** The commit that built these paths, from the verified token. What the verifier rebuilds. */
35	    readonly commitSha: string;
36	    /** The flake installables the job built, for the record. */
37	    readonly installables: readonly string[];
38	    /** The store paths whose closures must stay alive. */
39	    readonly storePaths: readonly string[];
40	}
41	
42	/**
43	 * Serialise a lease.
44	 *
45	 * Golden-locked: the Worker writes it, the collector and the verifier read it, and a nightly job
46	 * depends on the shape. Keys are emitted in a fixed order so a diff between two runs is legible.
47	 */
48	export function serializeLease(lease: LeaseDocument): string {
49	    return `${JSON.stringify(
50	        {
51	            project: String(lease.project),
52	            renewedAtMs: Number(lease.renewedAtMs),
53	            repository: lease.repository,
54	            ref: lease.ref,
55	            runId: lease.runId,
56	            commitSha: lease.commitSha,
57	            installables: lease.installables,
58	            storePaths: lease.storePaths,
59	        },
60	        undefined,
61	        2,
62	    )}\n`;
63	}
64	
65	/** A field that must be a string, defaulting when absent so an older document still reads. */
66	function textField(raw: Record<string, unknown>, name: string): string {
67	    const value = raw[name];
68	    return typeof value === 'string' ? value : UNKNOWN_CLAIM;
69	}
70	
71	/** A field that must be an array of strings. */
72	function listField(raw: Record<string, unknown>, name: string): readonly string[] {
73	    const value = raw[name];
74	    if (!Array.isArray(value)) {
75	        return [];
76	    }
77	    return value.filter((entry): entry is string => typeof entry === 'string');
78	}
79	
80	/**
81	 * Parse a lease.
82	 *
83	 * Defensive about everything except the two fields the collector's safety depends on. A missing
84	 * audit field degrades to `unknown`, because refusing to read a lease over incomplete provenance
85	 * would make the collector fail — and a collector that cannot read a lease must abort rather than
86	 * proceed, so a lenient parse here is what keeps a cosmetic gap from looking like a reason to delete
87	 * (Invariant GC-NEVER-EATS-THE-LIVING).
88	 *
89	 * The project name and the renewal timestamp are not negotiable: without them there is no way to
90	 * know which project this is or whether it is still current.
91	 */
92	export function parseLease(text: string): Result<LeaseDocument> {
93	    let parsed: unknown;
94	    try {
95	        parsed = JSON.parse(text);
96	    } catch {
97	        return fail('malformed_roots', 'a lease document is JSON');
98	    }
99	    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
100	        return fail('malformed_roots', 'a lease document is a JSON object');
101	    }
102	
103	    const raw = parsed as Record<string, unknown>;
104	    const project = parseProjectName(typeof raw['project'] === 'string' ? raw['project'] : '');
105	    if (!project.ok) {
106	        return fail('malformed_roots', 'a lease document names a valid project');
107	    }
108	
109	    const renewedAtMs = raw['renewedAtMs'];
110	    if (typeof renewedAtMs !== 'number' || !Number.isSafeInteger(renewedAtMs) || renewedAtMs < 0) {
111	        return fail('malformed_roots', 'a lease document records when it was renewed');
112	    }
113	
114	    return ok({
115	        project: project.value,
116	        renewedAtMs: renewedAtMs as UnixMillis,
117	        repository: textField(raw, 'repository'),
118	        ref: textField(raw, 'ref'),
119	        runId: textField(raw, 'runId'),
120	        commitSha: textField(raw, 'commitSha'),
121	        installables: listField(raw, 'installables'),
122	        storePaths: listField(raw, 'storePaths'),
123	    });
124	}
125	
126	/** Whether a lease is recent enough to protect what it names. */
127	export function isLeaseActive(
128	    lease: LeaseDocument,
129	    nowMs: UnixMillis,
130	    retentionMs: number,
131	): boolean {
132	    // Computed forward from the renewal, so a clock that jumped backwards makes a lease look more
133	    // current rather than expired — the conservative direction for a decision that gates deletion.
134	    return nowMs - lease.renewedAtMs < retentionMs;
135	}
136	
