/**
 * The lease document — one per project, under `roots/{project}`.
 *
 * A lease is cachet's only garbage-collection state. There is no database: the collector
 * reads these documents, walks the closures of the paths they name, and treats everything unmarked
 * and older than the grace window as collectable (ADR 0001).
 *
 * Two consequences follow:
 *
 * - Last write wins. A lease asserts what a project needs now rather than a history of what it once
 *   needed. A renewal replaces the previous document wholesale, so a path that drops out of the
 *   closure stops being protected — which is the only reason the cache does not grow forever.
 * - Provenance comes from the verified token, never from the request body. The verifier rebuilds
 *   from what a lease records, so a commit SHA a client could choose for itself would be worthless.
 *
 * @module
 */

import { UNKNOWN_CLAIM } from '../constants.js';
import { fail, ok, type Result } from '../result.js';
import { parseProjectName, type ProjectName, type UnixMillis } from '../types.js';

/** What `roots/{project}` holds. */
export interface LeaseDocument {
    readonly project: ProjectName;
    /** When this lease was last renewed. The collector compares it against lease retention. */
    readonly renewedAtMs: UnixMillis;
    /** `owner/repo`, from the verified token. */
    readonly repository: string;
    /** The ref that renewed it — always the configured default branch, by the time it is written. */
    readonly ref: string;
    /** The workflow run, from the verified token. */
    readonly runId: string;
    /** The commit that built these paths, from the verified token. What the verifier rebuilds. */
    readonly commitSha: string;
    /** The flake installables the job built, for the record. */
    readonly installables: readonly string[];
    /** The store paths whose closures must stay alive. */
    readonly storePaths: readonly string[];
}

/**
 * Serialise a lease.
 *
 * Golden-locked: the Worker writes it, the collector and the verifier read it, and a nightly job
 * depends on the shape. Keys are emitted in a fixed order so a diff between two runs is legible.
 */
export function serializeLease(lease: LeaseDocument): string {
    return `${JSON.stringify(
        {
            project: String(lease.project),
            renewedAtMs: Number(lease.renewedAtMs),
            repository: lease.repository,
            ref: lease.ref,
            runId: lease.runId,
            commitSha: lease.commitSha,
            installables: lease.installables,
            storePaths: lease.storePaths,
        },
        undefined,
        2,
    )}\n`;
}

/** A field that must be a string, defaulting when absent so an older document still reads. */
function textField(raw: Record<string, unknown>, name: string): string {
    const value = raw[name];
    return typeof value === 'string' ? value : UNKNOWN_CLAIM;
}

/** A field that must be an array of strings. */
function listField(raw: Record<string, unknown>, name: string): readonly string[] {
    const value = raw[name];
    if (!Array.isArray(value)) {
        return [];
    }
    return value.filter((entry): entry is string => typeof entry === 'string');
}

/**
 * Parse a lease.
 *
 * Defensive about everything except the two fields the collector's safety depends on. A missing
 * audit field degrades to `unknown`, because refusing to read a lease over incomplete provenance
 * would make the collector fail — and a collector that cannot read a lease must abort rather than
 * proceed, so a lenient parse here is what keeps a cosmetic gap from looking like a reason to delete
 * (Invariant GC-NEVER-EATS-THE-LIVING).
 *
 * The project name and the renewal timestamp are not negotiable: without them there is no way to
 * know which project this is or whether it is still current.
 */
export function parseLease(text: string): Result<LeaseDocument> {
    let parsed: unknown;
    try {
        parsed = JSON.parse(text);
    } catch {
        return fail('malformed_roots', 'a lease document is JSON');
    }
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
        return fail('malformed_roots', 'a lease document is a JSON object');
    }

    const raw = parsed as Record<string, unknown>;
    const project = parseProjectName(typeof raw['project'] === 'string' ? raw['project'] : '');
    if (!project.ok) {
        return fail('malformed_roots', 'a lease document names a valid project');
    }

    const renewedAtMs = raw['renewedAtMs'];
    if (typeof renewedAtMs !== 'number' || !Number.isSafeInteger(renewedAtMs) || renewedAtMs < 0) {
        return fail('malformed_roots', 'a lease document records when it was renewed');
    }

    return ok({
        project: project.value,
        renewedAtMs: renewedAtMs as UnixMillis,
        repository: textField(raw, 'repository'),
        ref: textField(raw, 'ref'),
        runId: textField(raw, 'runId'),
        commitSha: textField(raw, 'commitSha'),
        installables: listField(raw, 'installables'),
        storePaths: listField(raw, 'storePaths'),
    });
}

/** Whether a lease is recent enough to protect what it names. */
export function isLeaseActive(
    lease: LeaseDocument,
    nowMs: UnixMillis,
    retentionMs: number,
): boolean {
    // Computed forward from the renewal, so a clock that jumped backwards makes a lease look more
    // current rather than expired — the conservative direction for a decision that gates deletion.
    return nowMs - lease.renewedAtMs < retentionMs;
}

/** The bucket key a project's lease lives under. */
export function leaseKeyForProject(project: ProjectName, prefix: string): string {
    return `${prefix}${String(project)}`;
}

/** Recover a project name from a lease key. */
export function projectFromLeaseKey(key: string, prefix: string): Result<ProjectName> {
    if (!key.startsWith(prefix)) {
        return fail('malformed_key', 'a lease key begins with the roots prefix');
    }
    return parseProjectName(key.slice(prefix.length));
}

