const NIX32: &[u8] = b"REDACTED";
const NAME_CHARS: &[u8] = b"REDACTED.?=_";

fn draw_nix32(tc: &TestCase, len: usize) -> String {
    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(60));
    (0..len)
        .map(|i| NIX32[usize::from(bytes[i % bytes.len().max(1)]) % NIX32.len()] as char)
        .collect()
}

fn draw_name(tc: &TestCase, len: usize) -> String {
    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(60));
    (0..len.max(1))
        .map(|i| NAME_CHARS[usize::from(bytes[i % bytes.len().max(1)]) % NAME_CHARS.len()] as char)
