fn lease_parse_is_total(tc: TestCase) {
    let bytes: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(600));
    let text = String::from_utf8_lossy(&bytes);
    let _ = cachet_core::lease::LeaseDocument::parse(&text);
}

