//! Incremental zstd decoding over ruzstd (CLAUDE.md §5): the upload
//! verification pipeline streams a stored NAR through this decoder while a
//! hasher counts, so a bomb is bounded by output accounting, not by
//! buffer size. Errors are typed and total: truncated frames, corrupt
//! frames, and over-limit output all answer in [`ZstdError`].

use std::io::Read;

/// Why a decode failed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ZstdError {
    /// The frame bytes are corrupt or truncated.
    CorruptFrame,
    /// The frame produced more bytes than the caller's limit allows: a
    /// bomb guard, enforced stream-side rather than by buffering.
    LimitExceeded,
    /// The stream ended mid-frame: the declared NarSize was not
    /// reproducible from these bytes.
    Truncated,
}

impl core::fmt::Display for ZstdError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(match self {
            Self::CorruptFrame => "corrupt zstd frame",
            Self::LimitExceeded => "decompressed size over the declared limit",
            Self::Truncated => "zstd stream ended mid-frame",
        })
    }
}

impl std::error::Error for ZstdError {}

/// One decoding pass over an in-memory frame. Exists for tests, the workerd
/// lane's harness, and the CLI; the worker's streaming path drives
/// [`ZstdStream`] instead.
///
/// # Errors
///
/// [`ZstdError`] on corrupt frames and on output over `limit` bytes.
pub fn decode_all(bytes: &[u8], limit: u64) -> Result<Vec<u8>, ZstdError> {
    let mut stream = ZstdStream::new(limit);
    stream.push(bytes)?;
    stream.finish()
}

/// The incremental decoder. Feeding is chunked by the caller; decoded
/// bytes come out per push; `finish` drains and validates completeness.
pub struct ZstdStream {
    decoder: Option<ruzstd::Decoder<Vec<u8>>>,
    output: Vec<u8>,
    limit: u64,
    decompressed: u64,
}

impl ZstdStream {
    /// Start a decode with an output cap. The cap should be the
    /// narinfo-declared NarSize: an honest NAR just fits, and a bomb
    /// cannot write past it.
    pub fn new(limit: u64) -> Self {
        Self {
            decoder: Some(ruzstd::Decoder::new(Vec::new())),
            output: Vec::new(),
            limit,
            decompressed: 0,
        }
    }

    /// Feed compressed bytes, receiving any decoded output they produce.
    ///
    /// # Errors
    ///
    /// [`ZstdError`] on corrupt frames or on output passing the limit.
    pub fn push(&mut self, bytes: &[u8]) -> Result<Vec<u8>, ZstdError> {
        let Some(decoder) = self.decoder.take() else {
            return Err(ZstdError::CorruptFrame);
        };
        let mut data = std::io::Cursor::new(bytes);
        let mut decoder = decoder;
        let mut buffer = vec![0u8; 64 * 1024];
        let mut produced = Vec::new();
        loop {
            match decoder.read(&mut buffer) {
                Ok(0) => {
                    if data.position() < data.get_ref().len() as u64 {
                        // Bytes remain but decode stalled: the frame is
                        // incomplete, and more input may still proceed.
                        break;
                    }
                    break;
                }
                Ok(n) => {
                    self.decompressed = self
                        .decompressed
                        .checked_add(u64::try_from(n).expect("len fits"))
                        .ok_or(ZstdError::LimitExceeded)?;
                    if self.decompressed > self.limit {
                        return Err(ZstdError::LimitExceeded);
                    }
                    produced.extend_from_slice(&buffer[..n]);
                }
                Err(ref e) if e.kind() == std::io::ErrorKind::UnexpectedEof => {
                    break;
                }
                Err(_) => return Err(ZstdError::CorruptFrame),
            }
        }
        self.output.extend_from_slice(&produced);
        self.decoder = Some(decoder);
        Ok(produced)
    }

    /// Drain and validate completeness: the whole input must have decoded
    /// into a finished frame.
    ///
    /// # Errors
    ///
    /// [`ZstdError::Truncated`] when the frame did not finish.
    pub fn finish(mut self) -> Result<Vec<u8>, ZstdError> {
        let Some(mut decoder) = self.decoder.take() else {
            return Err(ZstdError::CorruptFrame);
        };
        let mut buffer = vec![0u8; 64 * 1024];
        match decoder.read(&mut buffer) {
            Ok(_) => {}
            Err(_) => return Err(ZstdError::Truncated),
        }
        Ok(std::mem::take(&mut self.output))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const NAR_ZST: &[u8] = include_bytes!("../tests/fixtures/nix-signed/11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y.nar.zst");

    #[test]
    fn decodes_the_fixture_frame() {
        let plain = decode_all(NAR_ZST, 1_000_000).expect("the fixture decodes");
        assert_eq!(
            hex::encode(crate::sha256::sha256(&plain)),
            "fa15060475f784debf7dc8331ceca9e76ae633559df1f0f9860654afec2d95c5"
        );
    }

    #[test]
    fn a_truncated_frame_is_typed_not_panic() {
        let truncated = &NAR_ZST[..NAR_ZST.len() / 2];
        let outcome = decode_all(truncated, 1_000_000);
        assert!(matches!(
            outcome,
            Err(ZstdError::CorruptFrame) | Err(ZstdError::Truncated)
        ));
    }

    #[test]
    fn corruption_fails_cleanly() {
        let mut corrupted = NAR_ZST.to_vec();
        for byte in &mut corrupted[4..40] {
            *byte ^= 0xff;
        }
        assert!(decode_all(&corrupted, 1_000_000).is_err());
    }

    #[test]
    fn the_limit_is_enforced() {
        let outcome = decode_all(NAR_ZST, 10);
        assert_eq!(outcome, Err(ZstdError::LimitExceeded));
    }
}

