/// The incremental decoder. `push` feeds compressed chunks and returns
/// what they decoded to; `finish` validates that the stream ended on a
/// frame boundary.
pub struct ZstdStream {
    pipe: Pipe,
    // why: StreamingDecoder::new reads the frame header eagerly, and a
    // header can span pushes, so construction defers until the pipe has
    // enough to satisfy it; on failure the cursor rewinds and the next
    // push retries over the same bytes plus new ones.
    decoder: Option<ruzstd::StreamingDecoder<Pipe, ruzstd::FrameDecoder>>,
    limit: u64,
    decompressed: u64,
    closed: bool,
