1	//! Incremental zstd decoding over ruzstd (CLAUDE.md §5). The upload
2	//! verification pipeline streams a stored NAR through this decoder while a
3	//! hasher counts: a bomb is bounded by output accounting, never by buffer
4	//! size. Errors are typed and total: truncated frames, corrupt frames, and
5	//! over-limit output all answer in [`ZstdError`], and no input shape can
6	//! panic the decoder.
7	//!
8	//! The stream's contract with ruzstd: the frame decoder is invoked only
9	//! when the input pipe holds a watermark of [`ZSTD_BLOCK_WIRE_MAX`] bytes.
10	//! A zstd block body can never exceed 128 KiB on the wire, so every block
11	//! the decoder starts is guaranteed complete in its input, and a
12	//! mid-block truncation can only ever happen at a real end of input.
13	
14	use std::cell::RefCell;
15	use std::io::Read;
16	use std::rc::Rc;
17	
18	/// Bytes buffered ahead of the decoder: a zstd block body tops out at
19	/// 128 KiB on the wire, plus header and trailer slack. Any block started
20	/// with this much pending input is guaranteed completable, which is what
21	/// makes error mapping total: after the watermark, a failure can only be
22	/// corruption.
23	const ZSTD_BLOCK_WIRE_MAX: usize = 132_096;
24	
25	/// Bytes buffered before the decoder's header probe: the largest frame
26	/// header prefix a real producer emits.
27	const HEADER_PROBE_MAX: usize = 64;
28	
29	/// Why a decode failed.
30	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
31	pub enum ZstdError {
32	    /// The frame bytes are corrupt.
33	    CorruptFrame,
34	    /// The frame produced more bytes than the caller's limit allows: a
35	    /// bomb guard, enforced stream-side rather than by buffering.
36	    LimitExceeded,
37	    /// The stream ended mid-frame: the declared NarSize was not
38	    /// reproducible from these bytes.
39	    Truncated,
40	}
41	
42	impl core::fmt::Display for ZstdError {
43	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
44	        f.write_str(match self {
45	            Self::CorruptFrame => "corrupt zstd frame",
46	            Self::LimitExceeded => "decompressed size over the declared limit",
47	            Self::Truncated => "zstd stream ended mid-frame",
48	        })
49	    }
50	}
51	
52	impl std::error::Error for ZstdError {}
53	
54	/// The shared input pipe: the decoder reads from it, the producer appends
55	/// to it. An `io::Read` over a cursor into a shared vector, so appending
56	/// compressed chunks while a streaming decoder holds the pipe needs no
57	/// unsafe and no threads (workerd isolates are single-threaded).
58	#[derive(Clone, Default)]
59	struct Pipe {
60	    inner: Rc<RefCell<std::io::Cursor<Vec<u8>>>>,
61	}
62	
63	impl Pipe {
64	    /// Append compressed bytes; the cursor position is preserved so the
65	    /// reader resumes exactly where it left off.
66	    fn append(&self, bytes: &[u8]) {
67	        self.inner.borrow_mut().get_mut().extend_from_slice(bytes);
68	    }
69	
70	    /// The unread position, for header-probe rewinds.
71	    fn position(&self) -> u64 {
72	        self.inner.borrow().position()
73	    }
74	
75	    /// Rewind to a saved position: a failed probe must leave the reader
76	    /// exactly where it started, so the next attempt replays identical
77	    /// bytes.
78	    fn set_position(&self, position: u64) {
79	        self.inner.borrow_mut().set_position(position);
80	    }
81	
82	    /// Bytes the reader has not yet consumed.
83	    fn pending(&self) -> usize {
84	        let cursor = self.inner.borrow();
85	        cursor.get_ref().len() - usize::try_from(cursor.position()).expect("cursor ≤ len")
86	    }
87	}
88	
89	impl Read for Pipe {
90	    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
91	        self.inner.borrow_mut().read(buf)
92	    }
93	}
94	
95	/// The incremental decoder. `push` feeds compressed chunks and returns
96	/// what they decoded to; `finish` closes the stream and validates that
97	/// the frame completed.
98	pub struct ZstdStream {
99	    pipe: Pipe,
100	    // why: FrameDecoder::init reads the frame header eagerly, and a header
101	    // can span pushes, so construction defers until the pipe has enough to
102	    // satisfy it; on failure the cursor rewinds and the next push retries
103	    // over identical bytes plus new ones.
104	    decoder: Option<Box<ruzstd::FrameDecoder>>,
105	    limit: u64,
106	    decompressed: u64,
107	    closed: bool,
108	}
109	
110	impl ZstdStream {
111	    /// Start a decode with an output cap. The cap should be the
112	    /// narinfo-declared NarSize: an honest NAR just fits, and a bomb
113	    /// cannot write past it.
114	    pub fn new(limit: u64) -> Self {
115	        Self {
116	            pipe: Pipe::default(),
117	            decoder: None,
118	            limit,
119	            decompressed: 0,
120	            closed: false,
