1	//! The collector's pure algorithm (CLAUDE.md §4): closure walk, gates,
2	//! deletion planning, and the run report. Everything destructive is decided
3	//! here as data, over injected inputs, so every catastrophic shape has a
4	//! test before it has a deployment: the driver in cachet-worker only
5	//! executes what these functions return.
6	//!
7	//! The laws: marked is never swept, reserved keys are never swept, narinfos
8	//! delete before NARs, and any gate trip aborts the run with nothing
9	//! deleted.
10	
11	use std::collections::{BTreeMap, BTreeSet, VecDeque};
12	
13	use crate::constants::{CLOSURE_WALK_PATHS_MAX, SWEEP_MAX_FRACTION};
14	use crate::keys::{NarKey, is_reserved_key};
15	use crate::narinfo::Narinfo;
16	use crate::types::{StorePathHash, UnixMillis};
17	
18	/// A gate trip: the run aborts and deletes nothing. Any of these means the
19	/// picture of the cache was untrustworthy in a way that makes deletion
20	/// unsafe, and the report names it so the run is debuggable.
21	#[derive(Debug, Clone, PartialEq, Eq)]
22	pub enum GateTrip {
23	    /// A root store path whose narinfo could not be read: the walk would
24	    /// see less than one lease protects.
25	    UnreadableRootNarinfo {
26	        /// The root hash that failed to read.
27	        hash: StorePathHash,
28	    },
29	    /// A lease document that will not parse: its protection is unknown.
30	    UnparseableLease {
31	        /// The lease's bucket key.
32	        key: String,
33	    },
34	    /// The R2 listing could not be fully enumerated in this run.
35	    InventoryTruncated,
36	    /// The project lease listing could not be fully enumerated.
37	    LeasesTruncated,
38	    /// The closure walk hit its visited-path cap.
39	    WalkBudgetExhausted {
40	        /// The number of paths visited when the cap tripped.
41	        visited: usize,
42	    },
43	    /// Deleting the candidates would remove more than the configured
44	    /// fraction of the path universe.
45	    SweepFractionExceeded {
46	        /// Candidate narinfo count.
47	        deletions: usize,
48	        /// Total narinfo inventory.
49	        inventory: usize,
50	    },
51	    /// The generation document is corrupt: sweeping without a reliable
52	    /// epoch would leave the edge serving deleted objects.
53	    GenerationCorrupt,
54	}
55	
56	impl core::fmt::Display for GateTrip {
57	    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
58	        match self {
59	            Self::UnreadableRootNarinfo { hash } => write!(f, "unreadable root narinfo {hash}"),
60	            Self::UnparseableLease { key } => write!(f, "unparseable lease {key}"),
61	            Self::InventoryTruncated => f.write_str("inventory truncated"),
62	            Self::LeasesTruncated => f.write_str("leases truncated"),
63	            Self::WalkBudgetExhausted { visited } => {
64	                write!(f, "walk budget exhausted at {visited} paths")
65	            }
66	            Self::SweepFractionExceeded {
67	                deletions,
68	                inventory,
69	            } => write!(
70	                f,
71	                "sweep of {deletions}/{inventory} paths exceeds the fraction gate"
72	            ),
73	            Self::GenerationCorrupt => f.write_str("generation document corrupt"),
74	        }
75	    }
76	}
