/// Serialize the document in its canonical order: known fields first,
/// sorted references, then the signatures in arrival order, then the
/// unknown lines verbatim. `parse(serialize(x))` reproduces `x`.
pub fn serialize(&self) -> String {
    let mut out = String::new();
    out.push_str(&format!("StorePath: {}\n", self.store_path));
    out.push_str(&format!("URL: {}\n", self.url.as_str()));
    out.push_str(&format!("Compression: {}\n", self.compression));
    if let Some(hash) = &self.file_hash {
        out.push_str(&format!("FileHash: {hash}\n"));
    }
    if let Some(size) = self.file_size_bytes {
        out.push_str(&format!("FileSize: {size}\n"));
    }
    out.push_str(&format!("NarHash: {}\n", self.nar_hash));
    out.push_str(&format!("NarSize: {}\n", self.nar_size_bytes));
    // Canonical ordering of references matches the set nix builds when
    // it parses, so served bytes and the client-side fingerprint agree.
    out.push_str(&format!("References: {}\n", self.canonical_references().join(" ")));
    for signature in &self.signatures {
        out.push_str(&format!("Sig: {signature}\n"));
    }
    for line in &self.extra_lines {
        out.push_str(line);
        out.push('\n');
    }
    out
}

