    for chunk in seed.chunks_mut(8) {
        chunk.copy_from_slice(&tc.draw(gs::integers::<u64>()).to_le_bytes());
    }
    let fingerprint: Vec<u8> = tc.draw(gs::vecs(gs::integers::<u8>()).max_size(128));
