//! Incremental zstd decoding over ruzstd (CLAUDE.md §5). The upload
//! verification pipeline streams a stored NAR through this decoder while a
//! hasher counts: a bomb is bounded by output accounting, never by buffer
//! size. Errors are typed and total: truncated frames, corrupt frames, and
//! over-limit output all answer in [`ZstdError`], and no input shape can
//! panic the decoder.
//!
//! The stream's contract with ruzstd: the frame decoder is invoked only
//! when the input pipe holds a watermark of [`ZSTD_BLOCK_WIRE_MAX`] bytes.
//! A zstd block body can never exceed 128 KiB on the wire, so every block
//! the decoder starts is guaranteed complete in its input, and a
//! mid-block truncation can only ever happen at a real end of input.

use std::cell::RefCell;
use std::io::Read;
use std::rc::Rc;

/// Bytes buffered ahead of the decoder: a zstd block body tops out at
/// 128 KiB on the wire, plus header and trailer slack. Any block started
/// with this much pending input is guaranteed completable, which is what
/// makes error mapping total: after the watermark, a failure can only be
/// corruption.
const ZSTD_BLOCK_WIRE_MAX: usize = 132_096;

/// Bytes buffered before the decoder's header probe: the largest frame
/// header prefix a real producer emits.
const HEADER_PROBE_MAX: usize = 64;

/// Why a decode failed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ZstdError {
    /// The frame bytes are corrupt.
    CorruptFrame,
    /// The frame produced more bytes than the caller's limit allows: a
    /// bomb guard, enforced stream-side rather than by buffering.
    LimitExceeded,
    /// The stream ended mid-frame: the declared NarSize was not
    /// reproducible from these bytes.
    Truncated,
}

impl core::fmt::Display for ZstdError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        f.write_str(match self {
            Self::CorruptFrame => "corrupt zstd frame",
            Self::LimitExceeded => "decompressed size over the declared limit",
            Self::Truncated => "zstd stream ended mid-frame",
        })
    }
}

impl std::error::Error for ZstdError {}

/// The shared input pipe: the decoder reads from it, the producer appends
/// to it. An `io::Read` over a cursor into a shared vector, so appending
/// compressed chunks while a streaming decoder holds the pipe needs no
/// unsafe and no threads (workerd isolates are single-threaded).
#[derive(Clone, Default)]
struct Pipe {
    inner: Rc<RefCell<std::io::Cursor<Vec<u8>>>>,
}

impl Pipe {
    /// Append compressed bytes; the cursor position is preserved so the
    /// reader resumes exactly where it left off.
    fn append(&self, bytes: &[u8]) {
        self.inner.borrow_mut().get_mut().extend_from_slice(bytes);
    }

    /// The unread position, for header-probe rewinds.
    fn position(&self) -> u64 {
        self.inner.borrow().position()
    }

    /// Rewind to a saved position: a failed probe must leave the reader
    /// exactly where it started, so the next attempt replays identical
    /// bytes.
    fn set_position(&self, position: u64) {
        self.inner.borrow_mut().set_position(position);
    }

    /// Bytes the reader has not yet consumed.
    fn pending(&self) -> usize {
        let cursor = self.inner.borrow();
        cursor.get_ref().len() - usize::try_from(cursor.position()).expect("cursor ≤ len")
    }
}

impl Read for Pipe {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        self.inner.borrow_mut().read(buf)
    }
}

/// The incremental decoder. `push` feeds compressed chunks and returns
/// what they decoded to; `finish` closes the stream and validates that
/// the frame completed.
pub struct ZstdStream {
    pipe: Pipe,
    // why: FrameDecoder::init reads the frame header eagerly, and a header
    // can span pushes, so construction defers until the pipe has enough to
    // satisfy it; on failure the cursor rewinds and the next push retries
    // over identical bytes plus new ones.
    decoder: Option<Box<ruzstd::FrameDecoder>>,
    limit: u64,
    decompressed: u64,
    closed: bool,
}

impl ZstdStream {
    /// Start a decode with an output cap. The cap should be the
    /// narinfo-declared NarSize: an honest NAR just fits, and a bomb
    /// cannot write past it.
    pub fn new(limit: u64) -> Self {
        Self {
            pipe: Pipe::default(),
            decoder: None,
            limit,
            decompressed: 0,
            closed: false,
        }
    }

    /// Feed compressed bytes, returning the decoded output they produced.
    /// Output may lag input (frames decode in blocks); `finish` drains the
    /// remainder.
    ///
    /// # Errors
    ///
    /// [`ZstdError`] on corrupt frames, over-limit output, or (after
    /// [`ZstdStream::finish`]) on a stream that ends mid-frame.
    pub fn push(&mut self, bytes: &[u8]) -> Result<Vec<u8>, ZstdError> {
        self.pipe.append(bytes);
        let mut produced = Vec::new();

        if self.decoder.is_none() {
            let can_probe = self.pipe.pending() >= HEADER_PROBE_MAX || self.closed;
            if can_probe {
                let position = self.pipe.position();
                let mut decoder = Box::new(ruzstd::FrameDecoder::new());
                match decoder.init(&mut self.pipe) {
                    Ok(()) => self.decoder = Some(decoder),
                    Err(ruzstd::frame_decoder::FrameDecoderError::FailedToInitialize(_)) => {
                        self.pipe.set_position(position);
                        return Err(ZstdError::CorruptFrame);
                    }
                    Err(_) => {
                        self.pipe.set_position(position);
                        return if self.closed {
                            Err(ZstdError::Truncated)
                        } else {
                            Ok(produced)
                        };
                    }
                }
            } else {
                return Ok(produced);
            }
        }

        // Decode every block the watermark guarantees completable, then
        // collect. A finished frame is never re-fed: an empty read at that
        // point is stream end, not a new block.
        while !self
            .decoder
            .as_ref()
            .expect("decoder built above")
            .is_finished()
            && (self.pipe.pending() >= ZSTD_BLOCK_WIRE_MAX || self.closed)
        {
            let result = self
                .decoder
                .as_mut()
                .expect("decoder built above")
                .decode_blocks(&mut self.pipe, ruzstd::BlockDecodingStrategy::All);
            match result {
                Ok(_) => {
                    self.collect(&mut produced)?;
                }
                Err(error) => {
                    return Err(self.map_frame_error(&error));
                }
            }
        }
        Ok(produced)
    }

    /// Drain the decoder's collectable buffer with limit accounting.
    fn collect(&mut self, produced: &mut Vec<u8>) -> Result<(), ZstdError> {
        loop {
            let collected = self.decoder.as_mut().expect("decoder built").collect();
            let Some(bytes) = collected else {
                return Ok(());
            };
            if bytes.is_empty() {
                return Ok(());
            }
            self.decompressed = self
                .decompressed
                .checked_add(u64::try_from(bytes.len()).expect("len fits"))
                .ok_or(ZstdError::LimitExceeded)?;
            if self.decompressed > self.limit {
                return Err(ZstdError::LimitExceeded);
            }
            produced.extend_from_slice(&bytes);
        }
    }

    /// Frame errors mean corruption after the watermark (a block is always
    /// complete there); under it, on close, they mean truncation when the
    /// pipe drained empty mid-frame.
    fn map_frame_error(&self, error: &ruzstd::frame_decoder::FrameDecoderError) -> ZstdError {
        let _ = error;
        if self.closed && self.pipe.pending() == 0 {
            ZstdError::Truncated
        } else {
            ZstdError::CorruptFrame
        }
    }

    /// Signal the end of input and drain, returning the decoded tail.
    /// The frame must complete inside the already-fed bytes.
    ///
    /// # Errors
    ///
    /// [`ZstdError::Truncated`] when the frame never completed.
    pub fn finish(&mut self) -> Result<Vec<u8>, ZstdError> {
        self.closed = true;
        let tail = self.push(&[])?;
        let decoder = self.decoder.as_mut().expect("decoder built in push");
        if !decoder.is_finished() {
            return Err(ZstdError::Truncated);
        }
        Ok(tail)
    }

    /// Total decompressed bytes seen so far.
    pub const fn decompressed_bytes(&self) -> u64 {
        self.decompressed
    }
}

/// One decoding pass over an in-memory frame: used by tests, the workerd
/// lane's harness, and the CLI.
///
/// # Errors
///
/// [`ZstdError`] on corrupt or truncated frames and on output over
/// `limit` bytes.
pub fn decode_all(bytes: &[u8], limit: u64) -> Result<Vec<u8>, ZstdError> {
    let mut stream = ZstdStream::new(limit);
    let mut out = stream.push(bytes)?;
    out.extend(stream.finish()?);
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;

    const NAR_ZST: &[u8] = include_bytes!(
        "../../../fixtures/nix-signed/11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y.nar.zst"
    );
    const NAR_SHA256: &str = "fa15060475f784debf7dc8331ceca9e76ae633559df1f0f9860654afec2d95c5";

    #[test]
    fn decodes_the_fixture_frame() {
        let plain = decode_all(NAR_ZST, 1_000_000).expect("the fixture decodes");
        assert_eq!(hex::encode(crate::sha256::sha256(&plain)), NAR_SHA256);
    }

    #[test]
    fn awkward_chunking_decodes_identically() {
        for chunk_size in [1usize, 7, 61, 4096] {
            let mut stream = ZstdStream::new(1_000_000);
            let mut out = Vec::new();
            for chunk in NAR_ZST.chunks(chunk_size) {
                out.extend(stream.push(chunk).expect("chunks decode"));
            }
            out.extend(stream.finish().expect("the frame completes"));
            assert_eq!(hex::encode(crate::sha256::sha256(&out)), NAR_SHA256);
        }
    }

    #[test]
    fn a_truncated_frame_is_typed_not_panic() {
        let truncated = &NAR_ZST[..NAR_ZST.len() / 2];
        assert_eq!(
            decode_all(truncated, 1_000_000).unwrap_err(),
            ZstdError::Truncated
        );
    }

    #[test]
    fn corruption_fails_cleanly() {
        let mut corrupted = NAR_ZST.to_vec();
        for byte in &mut corrupted[4..40] {
            *byte ^= 0xff;
        }
        assert!(matches!(
            decode_all(&corrupted, 1_000_000),
            Err(ZstdError::CorruptFrame | ZstdError::Truncated)
        ));
    }

    #[test]
    fn the_limit_is_enforced() {
        assert_eq!(
            decode_all(NAR_ZST, 10).unwrap_err(),
            ZstdError::LimitExceeded
        );
    }
}

//! The lease document: one per project, under `roots/{project}`.
//!
//! A lease is cachet's only garbage-collection state. There is no database:
//! the collector reads these documents, walks the closures of the paths
//! they name, and treats everything unmarked and older than the grace
//! window as collectable.
//!
//! Two consequences follow. Last write wins: a lease asserts what a project
//! needs now rather than a history of what it once needed, so a renewal
//! replaces the previous document wholesale and a path that drops out of
//! the closure stops being protected — which is the only reason the cache
//! does not grow forever. And provenance comes from the verified OIDC
//! token, never from the request body: a commit SHA a client could choose
//! for itself would be worthless as an audit trail.

use crate::constants::UNKNOWN_CLAIM;
use crate::error::{ClientError, Result};
use crate::types::{ProjectName, UnixMillis};

/// What `roots/{project}` holds.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
pub struct LeaseDocument {
    /// The project this lease covers; also the key suffix.
    pub project: String,
    /// When this lease was last renewed, in epoch milliseconds. The
    /// collector compares it against lease retention.
    #[serde(rename = "renewedAtMs")]
    pub renewed_at_ms: u64,
    /// `owner/repo`, from the verified token.
    pub repository: String,
    /// The ref that renewed it: always the configured default branch by the
    /// time it is written.
    #[serde(rename = "ref")]
    pub ref_: String,
    /// The workflow run, from the verified token.
    #[serde(rename = "runId")]
    pub run_id: String,
    /// The commit that built these paths, from the verified token.
    #[serde(rename = "commitSha")]
    pub commit_sha: String,
    /// The flake installables the job built, for the record.
    pub installables: Vec<String>,
    /// The store paths whose closures must stay alive.
    #[serde(rename = "storePaths")]
    pub store_paths: Vec<String>,
}

impl LeaseDocument {
    /// Serialize the lease. Golden-locked: the worker writes it, the
    /// collector reads it, and offline tooling depends on the shape, so the
    /// keys emit in a fixed order with two-space indent and a trailing
    /// newline and a diff between two runs stays legible.
    pub fn serialize(&self) -> String {
        let mut body =
            serde_json::to_string_pretty(self).expect("the document fields are string-like");
        body.push('\n');
        body
    }

    /// Parse a lease, defensive about everything except the two fields the
    /// collector's safety depends on. A missing audit field degrades to
    /// `unknown`, because refusing to read a lease over incomplete provenance
    /// would make the collector fail, and a collector that cannot read a
    /// lease must abort rather than proceed: a lenient parse is what keeps a
    /// cosmetic gap from looking like a reason to delete. The project name
    /// and the renewal timestamp are not negotiable.
    ///
    /// # Errors
    ///
    /// [`ClientError::MalformedRoots`] when the body is not a JSON object,
    /// the project name is invalid, or the renewal time is missing or
    /// negative.
    pub fn parse(text: &str) -> Result<Self> {
        let value: serde_json::Value =
            serde_json::from_str(text).map_err(|_| ClientError::MalformedRoots)?;
        let raw = value.as_object().ok_or(ClientError::MalformedRoots)?;

        let project = raw
            .get("project")
            .and_then(serde_json::Value::as_str)
            .and_then(|text| ProjectName::parse(text).ok())
            .ok_or(ClientError::MalformedRoots)?;

        let renewed_at_ms = raw
            .get("renewedAtMs")
            .and_then(serde_json::Value::as_u64)
            .ok_or(ClientError::MalformedRoots)?;

        Ok(Self {
            project: project.as_str().to_string(),
            renewed_at_ms,
            repository: text_field(raw, "repository"),
            ref_: text_field(raw, "ref"),
            run_id: text_field(raw, "runId"),
            commit_sha: text_field(raw, "commitSha"),
            installables: list_field(raw, "installables"),
            store_paths: list_field(raw, "storePaths"),
        })
    }

    /// Whether the lease is recent enough to protect what it names at
    /// `now`. Computed forward from the renewal with a saturating clock
    /// delta, so a clock that jumped backwards makes a lease look more
    /// current rather than expired: the conservative direction for a
    /// decision that gates deletion.
    pub fn is_active(&self, now: UnixMillis, retention_ms: u64) -> bool {
        now.saturating_ms_since(UnixMillis::new(self.renewed_at_ms)) < retention_ms
    }
}

/// A field that must be a string, defaulting when absent so an older
/// document still reads.
fn text_field(raw: &serde_json::Map<String, serde_json::Value>, name: &str) -> String {
    raw.get(name)
        .and_then(serde_json::Value::as_str)
        .unwrap_or(UNKNOWN_CLAIM)
        .to_string()
}

/// A field that must be an array of strings, defaulting to empty.
fn list_field(raw: &serde_json::Map<String, serde_json::Value>, name: &str) -> Vec<String> {
    raw.get(name)
        .and_then(serde_json::Value::as_array)
        .map(|entries| {
            entries
                .iter()
                .filter_map(serde_json::Value::as_str)
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn body() -> String {
        serde_json::json!({
            "project": "my-org-my-repo",
            "renewedAtMs": 1_780_000_000_000_u64,
            "repository": "my-org/my-repo",
            "ref": "refs/heads/main",
            "runId": "123",
            "commitSha": "abc",
            "installables": [".#devShells.aarch64-darwin.default"],
            "storePaths": ["/nix/store/REDACTED.2"],
        })
        .to_string()
    }

    #[test]
    fn round_trip_preserves_every_field() {
        let document = LeaseDocument::parse(&body()).expect("a real document parses");
        let again = LeaseDocument::parse(&document.serialize()).expect("the own form parses");
        assert_eq!(document, again);
    }

    #[test]
    fn missing_provenance_defaults_to_unknown() {
        let sparse = r#"{"project":"my-org-my-repo","renewedAtMs":1780000000000}"#;
        let document = LeaseDocument::parse(sparse).expect("audit gaps degrade");
        assert_eq!(document.repository, "unknown");
        assert_eq!(document.commit_sha, "unknown");
        assert!(document.store_paths.is_empty());
    }

    #[test]
    fn project_and_renewal_are_not_negotiable() {
        for bad in [
            r"{}",
            r#"{"project":42,"renewedAtMs":1}"#,
            r#"{"project":"a..b","renewedAtMs":1}"#,
            r#"{"project":"ok","renewedAtMs":-1}"#,
            r#"{"project":"ok","renewedAtMs":"1"}"#,
            r"[]",
        ] {
            assert!(LeaseDocument::parse(bad).is_err(), "{bad} refused");
        }
    }

    #[test]
    fn backwards_clock_keeps_a_lease_active() {
        use crate::constants::LEASE_RETENTION_MS;
        let mut document = LeaseDocument::parse(&body()).expect("parses");
        document.renewed_at_ms = 1_780_000_000_000;
        // Reading the lease from one second in its past must not expire it.
        let behind = UnixMillis::new(document.renewed_at_ms - 1_000);
        assert!(document.is_active(behind, LEASE_RETENTION_MS));
        let beyond = UnixMillis::new(document.renewed_at_ms + LEASE_RETENTION_MS);
        assert!(!document.is_active(beyond, LEASE_RETENTION_MS));
    }
}

//! The auth decision policy (CLAUDE.md §1, §7): what a GitHub OIDC token
//! must prove to write, and how long a validated GitHub user token stays
//! believed for reads. These functions are total and clock-injected; the
//! worker's edge adapts headers and JWKS bytes into the values they
//! decide over.
//!
//! The boundaries, stated once: writes are OIDC-only; laptops are
//! read-only; an OIDC token's `repository_owner` must be one of the
//! configured orgs; lease renewal additionally requires the configured
//! default branch and a project equal to the token's `repository` claim.

use crate::constants::{
    ACCEPTED_ORGS_MAX, JWKS_CACHE_TTL_MS, OAUTH_STATE_TTL_MS, OIDC_CLOCK_TOLERANCE_MS,
    SESSION_TTL_MS, VERDICT_ALLOW_TTL_MS, VERDICT_DENY_TTL_MS,
};
use crate::error::{ClientError, Result};
use crate::types::{ProjectName, UnixMillis};

/// The OIDC issuer URL every token must carry exactly.
pub const OIDC_ISSUER: &str = "https://token.actions.githubusercontent.com";

/// The deployment configuration the policy checks against. Vars in the
/// stack supply it; production code never hardcodes identity.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OidcConfig {
    /// The GitHub orgs whose OIDC tokens may write.
    pub orgs: Vec<String>,
    /// The exact audience a token must name, one string, never a match
    /// against a list inside the token.
    pub audience: String,
    /// The default-branch ref lease renewal is pinned to.
    pub default_branch_ref: String,
}

impl OidcConfig {
    /// Validate the configuration itself: an empty org list, an org entry
    /// with whitespace, an empty audience, or more orgs than the cap is a
    /// deployment mistake, and the request path refuses it with
    /// `auth_unavailable` by construction because no token can pass the
    /// empty list. Validating here is cheaper than correcting a security
    /// boundary in production.
    pub fn validate(&self) -> Result<()> {
        if self.orgs.is_empty() || self.orgs.len() > ACCEPTED_ORGS_MAX {
            return Err(ClientError::AuthUnavailable);
        }
        if self
            .orgs
            .iter()
            .any(|org| org.is_empty() || org.bytes().any(|b| b.is_ascii_whitespace()))
        {
            return Err(ClientError::AuthUnavailable);
        }
        if self.audience.is_empty() || self.default_branch_ref.is_empty() {
            return Err(ClientError::AuthUnavailable);
        }
        Ok(())
    }
}

/// The claims a verified OIDC token proves, extracted for the rest of the
/// system.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OidcIdentity {
    /// `owner/repo` of the workflow run.
    pub repository: String,
    /// The owner half of `repository`.
    pub repository_owner: String,
    /// The ref the run happened on.
    pub ref_: String,
    /// The workflow run id, when present.
    pub run_id: String,
    /// The commit sha, when present.
    pub sha: String,
}

/// Read one required string claim; a missing or mistyped claim refuses the
/// token, it never degrades.
fn string_claim(raw: &serde_json::Value, name: &str) -> Result<String> {
    raw.get(name)
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .ok_or(ClientError::Unauthorized)
}

/// Read one required integer time claim.
fn time_claim(raw: &serde_json::Value, name: &str) -> Result<u64> {
    raw.get(name)
        .and_then(serde_json::Value::as_u64)
        .ok_or(ClientError::Unauthorized)
}

/// Check a decoded OIDC claim set against the deployment configuration.
/// Algorithm selection and signature verification happen before this runs;
/// this function decides whether a cryptographically valid token carries
/// what the deployment requires.
///
/// # Errors
///
/// [`ClientError::Unauthorized`] for issuer, audience, time, or shape
/// failures; [`ClientError::ForbiddenOrg`] for an out-of-org owner.
pub fn verify_claims(
    raw: &serde_json::Value,
    config: &OidcConfig,
    now: UnixMillis,
) -> Result<OidcIdentity> {
    config.validate()?;

    if string_claim(raw, "iss")? != OIDC_ISSUER {
        return Err(ClientError::Unauthorized);
    }
    // why: an aud that is an array is a *different* protocol obligation
    // (evaluate every entry), so it refuses rather than running partial
    // logic over one entry. Exact single-string equality is the whole
    // audience rule.
    match raw.get("aud") {
        Some(serde_json::Value::String(value)) if value == &config.audience => {}
        _ => return Err(ClientError::Unauthorized),
    }

    let now_ms = now.as_u64();
    let exp = time_claim(raw, "exp")?;
    if exp.checked_mul(1_000).ok_or(ClientError::Unauthorized)?
        < now_ms.saturating_sub(OIDC_CLOCK_TOLERANCE_MS)
    {
        return Err(ClientError::Unauthorized);
    }
    let iat = time_claim(raw, "iat")?;
    if iat.checked_mul(1_000).ok_or(ClientError::Unauthorized)?
        > now_ms.saturating_add(OIDC_CLOCK_TOLERANCE_MS)
    {
        return Err(ClientError::Unauthorized);
    }
    if let Some(nbf) = raw.get("nbf").and_then(serde_json::Value::as_u64) {
        if nbf.checked_mul(1_000).ok_or(ClientError::Unauthorized)?
            > now_ms.saturating_add(OIDC_CLOCK_TOLERANCE_MS)
        {
            return Err(ClientError::Unauthorized);
        }
    }

    let repository = string_claim(raw, "repository")?;
    let repository_owner = string_claim(raw, "repository_owner")?;
    let ref_ = string_claim(raw, "ref")?;

    // Exact membership in the configured list. No prefix matches, no
    // case folding: GitHub emits owner names in canonical form.
    if !config.orgs.iter().any(|org| org == &repository_owner) {
        return Err(ClientError::ForbiddenOrg);
    }

    Ok(OidcIdentity {
        repository,
        repository_owner,
        ref_,
        run_id: raw
            .get("run_id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or(crate::constants::UNKNOWN_CLAIM)
            .to_string(),
        sha: raw
            .get("sha")
            .and_then(serde_json::Value::as_str)
            .unwrap_or(crate::constants::UNKNOWN_CLAIM)
            .to_string(),
    })
}

/// The lease-renewal gate: renewal must come from the configured default
/// branch.
///
/// # Errors
///
/// [`ClientError::ForbiddenRef`] on any other ref.
pub fn require_default_branch(identity: &OidcIdentity, config: &OidcConfig) -> Result<()> {
    if identity.ref_ == config.default_branch_ref {
        Ok(())
    } else {
        Err(ClientError::ForbiddenRef)
    }
}

/// The tenancy gate: a token may renew only its own repository's lease.
///
/// # Errors
///
/// [`ClientError::ForbiddenProject`] when the project's name does not equal
/// the hyphenated repository claim.
pub fn require_project_binding(identity: &OidcIdentity, project: &ProjectName) -> Result<()> {
    let derived = ProjectName::from_repository(&identity.repository)?;
    if &derived == project {
        Ok(())
    } else {
        Err(ClientError::ForbiddenProject)
    }
}

/// The kind of decision the JWKS cache policy produces.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum JwksDecision {
    /// Serve the cached document; it is inside its TTL.
    UseCached,
    /// Fetch fresh; the cache is empty or expired.
    Fetch,
}

/// The per-isolate JWKS cache policy: fresh inside the TTL, fetch
/// otherwise. Stale-fallback on a failed fetch is the edge's choice, not
/// this policy's: a stale document is better than an outage, and the TTL
/// still bounds acceptance of rotated-away keys.
pub fn decide_jwks(fetched_at_ms: Option<u64>, now: UnixMillis) -> JwksDecision {
    match fetched_at_ms {
        Some(at) if now.saturating_ms_since(UnixMillis::new(at)) < JWKS_CACHE_TTL_MS => {
            JwksDecision::UseCached
        }
        _ => JwksDecision::Fetch,
    }
}

/// The unknown-kid rule: one refetch per request, never a loop.
pub fn refetch_once_allowed(already_refetched: bool) -> bool {
    !already_refetched
}

/// The verdict outcome for one GitHub user token.
#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct Verdict {
    /// The GitHub login the token authenticates as.
    pub login: String,
    /// Whether the login is a member of an accepted org.
    pub org_member: bool,
    /// When the verdict was produced, in epoch milliseconds.
    #[serde(rename = "checkedAtMs")]
    pub checked_at_ms: u64,
}

/// How long a verdict stays believed: admits expire slower than denials,
/// because revocation of a laptop credential must converge in minutes
/// while a fresh org member must stop bouncing on the API.
pub fn verdict_ttl_ms(allowed: bool) -> u64 {
    if allowed {
        VERDICT_ALLOW_TTL_MS
    } else {
        VERDICT_DENY_TTL_MS
    }
}

/// Whether a verdict remains believable at `now`.
pub fn verdict_fresh(verdict: &Verdict, now: UnixMillis) -> bool {
    now.saturating_ms_since(UnixMillis::new(verdict.checked_at_ms))
        < verdict_ttl_ms(verdict.org_member)
}

/// Whether a session created at `created_at_ms` is live at `now`. Absolute
/// expiry: sessions do not roll, because a quiet laptop should not extend
/// a credential horizon indefinitely.
pub fn session_live(created_at_ms: u64, now: UnixMillis) -> bool {
    now.saturating_ms_since(UnixMillis::new(created_at_ms)) < SESSION_TTL_MS
}

/// Whether an OAuth state token issued at `issued_at_ms` is valid at
/// `now`; consumed on use by the edge regardless.
pub fn oauth_state_valid(issued_at_ms: u64, now: UnixMillis) -> bool {
    now.saturating_ms_since(UnixMillis::new(issued_at_ms)) < OAUTH_STATE_TTL_MS
}

