    /// The 20-byte store-hash width: decode of encode is the identity, and
    /// the encoding stays 32 chars of alphabet.
    #[kani::proof]
    #[kani::unwind(35)]
    fn base32_20_round_trip() {
        let data: [u8; 20] = kani::any();
        let encoded = encode(&data);
        for c in encoded.bytes() {
            assert!(DIGITS.contains(&c));
