        let key = NixSecretKey::from_seed("k", &seed).expect("seeds derive");
        let sig = key.sign_fingerprint(&fingerprint);
        let (_, public) = parse_public_key(&key.public_key_text()).expect("our own public parses");
        assert!(verify_fingerprint(&fingerprint, &sig, &public));

        let tampered = format!("{fingerprint}x");
        assert!(!verify_fingerprint(&tampered, &sig, &public));
    }
}

