64	/// accepts `&VerifiedNar` and nothing else, which is what makes the order
65	/// verify-then-sign rather than a convention (CLAUDE.md §1).
66	///
67	/// FileHash and FileSize are set from the measured facts: where the client
68	/// declared them, verification proved them equal; where it omitted them,
69	/// the stored document gains the computed values, so what the cache serves
70	/// always describes the bytes it holds.
71	#[derive(Debug, Clone)]
72	pub struct VerifiedNar {
73	    narinfo: Narinfo,
74	}
75	
76	impl VerifiedNar {
77	    /// Verify the stored-NAR measurements against the narinfo's claims and
78	    /// produce the signable document.
79	    ///
80	    /// The nar claims run before the file claims: the decompressed side is
81	    /// what a client verifies after substituting, so its disagreement is
82	    /// reported first.
83	    ///
84	    /// # Errors
85	    ///
86	    /// [`ClientError::NarHashMismatch`] when the decompressed size or hash
87	    /// disagrees with `NarSize` or `NarHash`;
88	    /// [`ClientError::FileHashMismatch`] when the compressed hash disagrees
89	    /// with the hash the NAR key names, or with `FileHash` when declared,
90	    /// or the compressed size disagrees with `FileSize` when declared.
91	    pub fn verify(
92	        narinfo: &Narinfo,
93	        decompressed_size: u64,
94	        decompressed_hash_text: &str,
95	        compressed_hash_nix32: &str,
96	        compressed_size: u64,
97	    ) -> Result<Self> {
98	        if decompressed_size != narinfo.nar_size_bytes
99	            || decompressed_hash_text != narinfo.nar_hash
100	        {
101	            return Err(ClientError::NarHashMismatch);
102	        }
103	        if compressed_hash_nix32 != narinfo.url.file_hash() {
104	            return Err(ClientError::FileHashMismatch);
105	        }
106	        if narinfo
107	            .file_hash
108	            .as_ref()
109	            .is_some_and(|hash| *hash != format!("sha256:{compressed_hash_nix32}"))
110	        {
111	            return Err(ClientError::FileHashMismatch);
112	        }
113	        if narinfo
114	            .file_size_bytes
115	            .is_some_and(|size| size != compressed_size)
116	        {
