24	/// first (a malformed path is a 400 before any credential is read),
25	/// authorization second (an unauthenticated write is a 401 before any
26	/// 411), then the route's own guards. Everything outside the cache-object
27	/// grammars and the handshake is a 404.
28	#[event(fetch)]
29	async fn fetch(mut req: Request, env: Env, ctx: Context) -> Result<Response> {
30	    let method = req.method();
31	    // why: the Clock seam (CLAUDE.md §3): the one ambient sample per
32	    // request, injected everywhere below.
33	    let now = UnixMillis::new(worker::Date::now().as_millis());
34	    let path = req.path();
35	
36	    if method == Method::Get || method == Method::Head {
37	        if path == "/nix-cache-info" {
38	            return read::serve_cache_info();
39	        }
40	        if path.starts_with("/nar/") {
41	            let key = match parse_nar_request_path(&path) {
42	                Ok(key) => key,
43	                Err(code) => return error::problem_response(code),
44	            };
45	            return match method {
46	                Method::Head => read::head_object(&env, key.as_str(), ObjectKind::Nar).await,
47	                _ => read::serve_object(&env, &ctx, &path, key.as_str(), ObjectKind::Nar).await,
48	            };
49	        }
50	        if path.ends_with(NARINFO_KEY_SUFFIX) {
51	            let hash = match parse_narinfo_request_path(&path) {
52	                Ok(hash) => hash,
53	                Err(code) => return error::problem_response(code),
54	            };
55	            let bucket_key = format!("{hash}{NARINFO_KEY_SUFFIX}");
56	            return match method {
57	                Method::Head => read::head_object(&env, &bucket_key, ObjectKind::Narinfo).await,
58	                _ => {
59	                    read::serve_object(&env, &ctx, &path, &bucket_key, ObjectKind::Narinfo).await
60	                }
61	            };
62	        }
63	        return error::problem_response(ClientError::NotFound);
64	    }
65	
66	    if path.ends_with(NARINFO_KEY_SUFFIX) && method == Method::Put {
