import assert from 'node:assert/strict';
import { spawn, spawnSync } from 'node:child_process';
import crypto from 'node:crypto';
import { mkdtemp, readFile, rm, writeFile } from 'node:fs/promises';
import http from 'node:http';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';

const repoRoot = path.resolve(import.meta.dirname, '..');
const configPath = path.join(repoRoot, 'workerd', 'wrangler.toml');
const fixturesDir = path.resolve(process.argv[2] ?? path.join(repoRoot, 'fixtures', 'nix-signed'));
const laneFixturesDir = path.join(repoRoot, 'workerd', 'fixtures');

const NARINFO_KEY = 'qvqa04f0m85m0a6xxnan5vxnwg2jkgl9.narinfo';
const NAR_FILE = '11lx23nn3dpc8mqp0ncnm6wqcxs6pfw32bp8n9c1fkafyzjvn16y.nar.zst';
const NAR_KEY = `nar/${NAR_FILE}`;
const OTHER_NARINFO = '33333333333333333333333333333333.narinfo';

// The lane's OIDC stand-in: one RSA pair per run, a stub JWKS server on
// loopback, and tokens minted fresh (they can never rot like committed
// token fixtures would).
const { publicKey: jwksPublicKey, privateKey: jwksPrivateKey } = crypto.generateKeyPairSync('rsa', {
  modulusLength: 2048,
});
const jwksJwk = { kid: 'lane-1', ...jwksPublicKey.export({ format: 'jwk' }) };
const jwksServer = http.createServer((req, res) => {
  if (req.url === '/jwks.json') {
    res.writeHead(200, { 'content-type': 'application/json' });
    res.end(JSON.stringify({ keys: [jwksJwk] }));
  } else {
    res.writeHead(404);
    res.end();
  }
});
await new Promise((resolve) => jwksServer.listen(0, '127.0.0.1', resolve));
const jwksUrl = `http://127.0.0.1:${jwksServer.address().port}/jwks.json`;
process.on('exit', () => jwksServer.close());

const b64url = (data) =>
  Buffer.from(data).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

// Mint a lane OIDC token: claims the policy requires, overridable key by
// key for the rejection cases.
function mint(overrides = {}) {
  const header = b64url(JSON.stringify({ alg: overrides.alg ?? 'RS256', typ: 'JWT', kid: 'lane-1' }));
  const nowSec = Math.floor(Date.now() / 1000);
  const claims = {
    iss: 'https://token.actions.githubusercontent.com',
    aud: 'cachet-lane',
    exp: nowSec + 600,
    iat: nowSec - 10,
    repository: 'lane-org/lane-repo',
    repository_owner: 'lane-org',
    ref: 'refs/heads/main',
    run_id: '41',
    sha: 'abc',
    ...overrides,
  };
  delete claims.alg;
  const payload = b64url(JSON.stringify(claims));
  const signature = crypto.sign('RSA-SHA256', Buffer.from(`${header}.${payload}`), jwksPrivateKey);
  return `${header}.${payload}.${b64url(signature)}`;
}

// The lane's signing key enters as .dev.vars, the same way a deployment's
// would; it is committed material in workerd/fixtures, and the file is
// cleaned up when the lane ends.
const devVarsPath = path.join(repoRoot, 'workerd', '.dev.vars');
const laneSigningSecret = (await readFile(path.join(laneFixturesDir, 'signing-key.secret'), 'utf8')).trimEnd();
process.on('exit', () => {
  spawnSync('rm', ['-f', devVarsPath]);
});

