#[test]
fn rsa_bisect() {
    use base64ct::{Base64UrlUnpadded, Encoding};
    use rsa::pkcs8::DecodePrivateKey;
    let private_pem = std::env::var("PRIV_PEM").unwrap();
    let private_key = rsa::RsaPrivateKey::from_pkcs8_pem(&private_pem).expect("pem parses");
    let public_key = private_key.to_public_key();

    // Direction 1: our verify over OUR OWN crate-api signature equivalent:
    // the rsa crate's own round trip over a fixed message.
    let scheme = rsa::Pkcs1v15Sign::new::<sha2::Sha256>();
    let sig = private_key.sign_with_rng(&mut rsa::rand_core::OsRng, scheme.clone(), b"hello").expect("signs");
    println!(
        "rsa-crate self round trip: {:?}",
        public_key.verify(scheme.clone(), b"hello", &sig)
    );

    // Direction 2: our verify_rs256 over the node-minted token, with the
    // JWK rebuilt from the SAME private key's own public parts.
    let token = std::env::var("TOKEN").unwrap();
    let decoded = cachet_crypto::rs256::decode_jwt(&token).expect("decodes");
    let jwk = cachet_crypto::rs256::RsaJwk {
        kid: "x".into(),
        kty: "RSA".into(),
        n: Base64UrlUnpadded::encode_string(public_key.n().to_bytes_be().as_slice()),
        e: Base64UrlUnpadded::encode_string(public_key.e().to_bytes_be().as_slice()),
    };
    println!(
        "node-token vs pem-rebuilt jwk: {:?}",
        cachet_crypto::rs256::verify_rs256(&jwk, &decoded.signing_input, &decoded.signature)
    );

    // Direction 3: node token vs the jwk the STUB served (the exact lane path).
    let stub_jwk: cachet_crypto::rs256::RsaJwk =
        serde_json::from_str(&std::env::var("STUB_JWK").unwrap()).expect("jwk json");
    let same_modulus = stub_jwk.n == jwk.n;
    println!("stub jwk modulus equals pem modulus: {same_modulus}");
    println!(
        "node-token vs stub jwk: {:?}",
        cachet_crypto::rs256::verify_rs256(&stub_jwk, &decoded.signing_input, &decoded.signature)
    );
}
EOF
